<?php
/**  * Export Admin Receivables Aging Summary (Excel/CSV)  * Admin oversight of all station receivables  */
if (session_status() === PHP_SESSION_NONE) session_start();  require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';
require_login();  $me = current_user();
$role = role_key($me['role'] ?? '');  if (!in_array($role, ['admin', 'superadmin'])) {  die('Access denied');
}  $format = $_GET['format'] ?? 'excel';
$station_filter = $_GET['station_id'] ?? '';  // Validate format
if (!in_array($format, ['excel', 'csv'])) {  die('Invalid format');
}  try {  // Build receivables aging query  $where_clause = "WHERE 1=1";  $params = [];  if ($station_filter !== '') {  $where_clause .= " AND s.id = ?";  $params[] = (int)$station_filter;  }  // Fetch all receivables across all stations  $query = $pdo->prepare("  SELECT  s.name AS station_name,  c.name AS customer_name,  c.contact_number,  c.credit_limit,  c.balance AS total_balance,  (SELECT COUNT(*)  FROM merchandise_transactions mt  WHERE mt.customer_id = c.id  AND mt.payment_status IN ('Pending Payment', 'Partial Payment')  ) +  (SELECT COUNT(*)  FROM job_orders jo  WHERE jo.customer_id = c.id  AND jo.payment_status IN ('Pending Payment', 'Partial Payment')  ) AS pending_txn_count,  (SELECT SUM(mt.total_amount - COALESCE(mt.amount_paid, 0))  FROM merchandise_transactions mt  WHERE mt.customer_id = c.id  AND mt.payment_status IN ('Pending Payment', 'Partial Payment')  AND DATEDIFF(CURDATE(), DATE(mt.created_at)) <= 30  ) AS balance_0_30,  (SELECT SUM(mt.total_amount - COALESCE(mt.amount_paid, 0))  FROM merchandise_transactions mt  WHERE mt.customer_id = c.id  AND mt.payment_status IN ('Pending Payment', 'Partial Payment')  AND DATEDIFF(CURDATE(), DATE(mt.created_at)) BETWEEN 31 AND 60  ) AS balance_31_60,  (SELECT SUM(mt.total_amount - COALESCE(mt.amount_paid, 0))  FROM merchandise_transactions mt  WHERE mt.customer_id = c.id  AND mt.payment_status IN ('Pending Payment', 'Partial Payment')  AND DATEDIFF(CURDATE(), DATE(mt.created_at)) > 60  ) AS balance_over_60,  c.status  FROM customers c  INNER JOIN stations s ON c.station_id = s.id  $where_clause  AND c.balance > 0  ORDER BY s.name, c.balance DESC  LIMIT 1000  ");  $query->execute($params);  $receivables = $query->fetchAll(PDO::FETCH_ASSOC);  if (empty($receivables)) {  die('No receivables data found');  }  // Export based on format  if ($format === 'csv') {  header('Content-Type: text/csv; charset=utf-8');  header('Content-Disposition: attachment; filename="admin_receivables_aging_' . date('Y-m-d_His') . '.csv"');  $output = fopen('php://output', 'w');  fputcsv($output, ['Station', 'Customer', 'Contact', 'Credit Limit', 'Total Balance', 'Pending Txns', '0-30 Days', '31-60 Days', 'Over 60 Days', 'Status']);  foreach ($receivables as $row) {  fputcsv($output, [  $row['station_name'],  $row['customer_name'],  $row['contact_number'] ?: 'N/A',  number_format((float)$row['credit_limit'], 2),  number_format((float)$row['total_balance'], 2),  (int)$row['pending_txn_count'],  number_format((float)($row['balance_0_30'] ?? 0), 2),  number_format((float)($row['balance_31_60'] ?? 0), 2),  number_format((float)($row['balance_over_60'] ?? 0), 2),  $row['status']  ]);  }  fclose($output);  exit;  } elseif ($format === 'excel') {  header('Content-Type: application/vnd.ms-excel; charset=utf-8');  header('Content-Disposition: attachment; filename="admin_receivables_aging_' . date('Y-m-d_His') . '.xls"');  echo '<html xmlns:x="urn:schemas-microsoft-com:office:excel">';  echo '<head><meta charset="UTF-8">';  echo '<style>table{border-collapse:collapse;}th,td{border:1px solid #ddd;padding:8px;}th{background-color:#002F70;color:white;font-weight:bold;}</style>';  echo '</head><body>';  echo '<h2 style="color:#002F70;">Receivables Aging Summary</h2>';  echo '<p>Generated: ' . date('F d, Y h:i A') . ' | Admin: ' . htmlspecialchars($me['name']) . '</p>';  echo '<table>';  echo '<thead><tr>';  echo '<th>Station</th><th>Customer</th><th>Contact</th><th>Credit Limit</th><th>Total Balance</th><th>Pending Txns</th>';  echo '<th>0-30 Days</th><th>31-60 Days</th><th>Over 60 Days</th><th>Status</th>';  echo '</tr></thead><tbody>';  $total_balance = 0;  $total_0_30 = 0;  $total_31_60 = 0;  $total_over_60 = 0;  foreach ($receivables as $row) {  $total_balance += (float)$row['total_balance'];  $total_0_30 += (float)($row['balance_0_30'] ?? 0);  $total_31_60 += (float)($row['balance_31_60'] ?? 0);  $total_over_60 += (float)($row['balance_over_60'] ?? 0);  echo '<tr>';  echo '<td>' . htmlspecialchars($row['station_name']) . '</td>';  echo '<td>' . htmlspecialchars($row['customer_name']) . '</td>';  echo '<td>' . htmlspecialchars($row['contact_number'] ?: 'N/A') . '</td>';  echo '<td style="text-align:right;">₱' . number_format((float)$row['credit_limit'], 2) . '</td>';  echo '<td style="text-align:right;">₱' . number_format((float)$row['total_balance'], 2) . '</td>';  echo '<td style="text-align:center;">' . (int)$row['pending_txn_count'] . '</td>';  echo '<td style="text-align:right;">₱' . number_format((float)($row['balance_0_30'] ?? 0), 2) . '</td>';  echo '<td style="text-align:right;">₱' . number_format((float)($row['balance_31_60'] ?? 0), 2) . '</td>';  echo '<td style="text-align:right;">₱' . number_format((float)($row['balance_over_60'] ?? 0), 2) . '</td>';  echo '<td>' . htmlspecialchars($row['status']) . '</td>';  echo '</tr>';  }  echo '<tr style="background:#f0f4ff;font-weight:bold;">';  echo '<td colspan="4" style="text-align:right;">TOTAL:</td>';  echo '<td style="text-align:right;">₱' . number_format($total_balance, 2) . '</td>';  echo '<td></td>';  echo '<td style="text-align:right;">₱' . number_format($total_0_30, 2) . '</td>';  echo '<td style="text-align:right;">₱' . number_format($total_31_60, 2) . '</td>';  echo '<td style="text-align:right;">₱' . number_format($total_over_60, 2) . '</td>';  echo '<td></td>';  echo '</tr>';  echo '</tbody></table></body></html>';  exit;  }  } catch (Exception $e) {  die('Export error: ' . $e->getMessage());
}
